/// <reference types="@figma/plugin-typings" />
import { HandlerContext, requireNode, findNode, isParentNode, getNodeByIdSafe } from "../context.js";
import { resolveParent, insertInto } from "../insert.js";
import { toPaints, toEffects } from "../paints.js";
import { loadNodeFonts, loadFontWithFallback, DEFAULT_FONT } from "../fonts.js";
import { serializeNode } from "../serialize.js";
import { applyTextAlign } from "./text.js";
import { findVariableByName, bindVariableToField, expandBindableField } from "./tokens.js";
import {
  parseLineHeight,
  parseLetterSpacing,
  resolveTextStyle,
  applyTextStyleToNode,
  resolveEffectStyle,
  applyEffectStyleToNode,
} from "./styles.js";
import { err, nodeNotFound } from "../errors.js";
import { ErrorCode } from "../../shared/protocol.js";
import {
  InsertAt,
  normalizePadding,
  resolveUniformCornerRadius,
} from "../layout-math.js";
import { isHexColor, isRgbObject } from "../color-util.js";
import { setArrowPolyline, setPolyline, toPoints } from "../vector-path.js";

/**
 * General property setter: fills/strokes/effects, auto-layout, text, geometry.
 * Re-applies textAutoResize after any reparent to dodge the Figma quirk where
 * moving a text node can reset its sizing behaviour.
 */
export async function modify(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  const node = await requireNode(p.nodeId ?? p.id);
  const props = (p.props ?? p) as Record<string, unknown>;

  if (props.name !== undefined && typeof props.name === "string") {
    node.name = props.name;
  }

  // Text props first (need font loaded before characters).
  if (node.type === "TEXT") {
    await modifyText(node as TextNode, props, ctx);
  }

  if (props.fills !== undefined && "fills" in node) {
    (node as GeometryMixin).fills = toPaints(props.fills);
  } else if (
    // `fill`/`stroke` are the single-colour aliases create() also takes: a
    // hex string or the Figma {r,g,b[,a]} object.
    ((typeof props.fill === "string" && isHexColor(props.fill)) ||
      isRgbObject(props.fill)) &&
    "fills" in node
  ) {
    (node as GeometryMixin).fills = toPaints(props.fill);
  }
  if (props.strokes !== undefined && "strokes" in node) {
    (node as GeometryMixin).strokes = toPaints(props.strokes);
  } else if (
    // The `stroke` alias used to be read only on create — modify() silently
    // dropped it, so an outline update had to go through `strokes`.
    ((typeof props.stroke === "string" && isHexColor(props.stroke)) ||
      isRgbObject(props.stroke)) &&
    "strokes" in node
  ) {
    (node as GeometryMixin).strokes = toPaints(props.stroke);
  }
  if (typeof props.strokeWeight === "number" && "strokeWeight" in node) {
    (node as MinimalStrokesMixin).strokeWeight = props.strokeWeight;
  }
  // Per-side weights, after strokeWeight (which resets all four) — the same
  // order create() applies them in.
  for (const side of ["strokeTopWeight", "strokeRightWeight", "strokeBottomWeight", "strokeLeftWeight"] as const) {
    if (typeof props[side] === "number" && side in node) {
      (node as unknown as Record<string, number>)[side] = props[side] as number;
    }
  }
  // Stroke DETAIL. create() has honoured these since it learned to draw arrow
  // heads and dashed dividers; modify() never did, so a stroke property that
  // could be set when the node was made could not be CHANGED afterwards — and
  // the failure is silent, which is the worst shape for it. `strokeAlign` is
  // the one that bites: Figma's default is INSIDE, so two rectangles sharing
  // an edge each paint their border inside themselves and the shared line
  // comes out double-width. A focus ring that has to sit OUTSIDE its control
  // cannot be expressed any other way, and going through the bridge silently
  // returned it to INSIDE.
  if (typeof props.strokeAlign === "string" && "strokeAlign" in node) {
    (node as MinimalStrokesMixin).strokeAlign =
      props.strokeAlign as "CENTER" | "INSIDE" | "OUTSIDE";
  }
  if (typeof props.strokeCap === "string" && "strokeCap" in node) {
    (node as unknown as { strokeCap: StrokeCap }).strokeCap = props.strokeCap as StrokeCap;
  }
  if (typeof props.strokeJoin === "string" && "strokeJoin" in node) {
    (node as unknown as { strokeJoin: StrokeJoin }).strokeJoin = props.strokeJoin as StrokeJoin;
  }
  if (Array.isArray(props.dashPattern) && "dashPattern" in node) {
    (node as unknown as { dashPattern: readonly number[] }).dashPattern =
      props.dashPattern.filter((v): v is number => typeof v === "number");
  }
  if (props.effects !== undefined && "effects" in node) {
    (node as BlendMixin).effects = toEffects(props.effects);
  }
  // Named styles. `create` resolves these and fails fast on a wrong name;
  // `modify` read neither, so a text layer could be GIVEN a style at birth and
  // never moved to another one — and applying a style is the right route for
  // type, so the gap pushed callers back to raw fontSize/lineHeight.
  // Resolved before writing, so a typo is an error the caller can act on
  // rather than a node that silently keeps its old look.
  if (typeof props.textStyle === "string" && node.type === "TEXT") {
    const style = await resolveTextStyle(props.textStyle);
    if (style) await applyTextStyleToNode(node as TextNode, style);
  }
  if (typeof props.effectStyle === "string" && "effects" in node) {
    const style = await resolveEffectStyle(props.effectStyle);
    if (style) await applyEffectStyleToNode(node as SceneNode, style);
  }
  // Shape geometry that is settable for the life of the node. `points` was
  // already here for VECTOR; these were not, so a polygon created with five
  // sides was a pentagon forever.
  if (typeof props.pointCount === "number" && "pointCount" in node) {
    (node as unknown as { pointCount: number }).pointCount = Math.max(3, Math.round(props.pointCount));
  }
  if (typeof props.innerRadius === "number" && "innerRadius" in node) {
    (node as unknown as { innerRadius: number }).innerRadius = props.innerRadius;
  }
  if (Array.isArray(props.vectorPaths) && node.type === "VECTOR") {
    (node as VectorNode).vectorPaths = props.vectorPaths as VectorPaths;
  }

  // Token bindings, LAST — they have to land on the final paints and layout,
  // the same order create uses.
  //
  // `tokens` was on the creation-only list until somebody pointed out it sits
  // on the wrong side of the line: a binding is not a fact about a node's
  // birth, it is a live property, and re-binding EXISTING nodes is exactly
  // what a token migration is. Without it that job went through applyVariable
  // one field at a time — nine calls a node for a fill, four corner radii and
  // four paddings — which is not merely tedious: each call is its own
  // round-trip, so a partial failure leaves a node half-migrated with nothing
  // saying which half.
  //
  // A name that does not resolve throws BEFORE anything is bound, so a typo
  // cannot leave a node partly rebound.
  const tokenSpec = props.tokens;
  if (tokenSpec && typeof tokenSpec === "object" && !Array.isArray(tokenSpec)) {
    const wanted: Array<{ field: string; variable: Variable }> = [];
    for (const [field, raw] of Object.entries(tokenSpec as Record<string, unknown>)) {
      const tokenName = String(raw).replace(/^\$/, "");
      const variable = await findVariableByName(tokenName);
      if (!variable) {
        throw err(
          ErrorCode.INVALID_PARAMS,
          `No variable named "${tokenName}" (for field "${field}"). Nothing was bound.`,
          "Check the token name with figma_read get_variables, or create it first.",
        );
      }
      for (const f of expandBindableField(field)) wanted.push({ field: f, variable });
    }
    for (const b of wanted) bindVariableToField(node, b.field, b.variable);
  }
  if (typeof props.opacity === "number" && "opacity" in node) {
    (node as BlendMixin).opacity = props.opacity;
  }
  // VECTOR geometry: the same `points` shorthand create takes, so a caller can
  // adjust a line it already drew (and `endArrow` keeps the head on its end).
  if (node.type === "VECTOR" && Array.isArray(props.points)) {
    const pts = toPoints(props.points);
    if (pts.length < 2) {
      ctx.warn("points needs at least two [x,y] pairs — the vector was left alone.");
    } else if (props.endArrow === false) {
      setPolyline(node as VectorNode, pts, props.closed === true);
    } else {
      await setArrowPolyline(node as VectorNode, pts);
    }
  }
  applyCornerRadii(node, props);
  if (typeof props.clipsContent === "boolean" && "clipsContent" in node) {
    (node as FrameNode).clipsContent = props.clipsContent;
  }
  if (typeof props.visible === "boolean") node.visible = props.visible;
  if (typeof props.rotation === "number" && "rotation" in node) {
    (node as LayoutMixin).rotation = props.rotation;
  }

  // Auto-layout props.
  if ("layoutMode" in node) {
    applyLayoutProps(node as FrameNode, props);
  } else {
    // A rectangle/text/vector inside an auto-layout frame still takes
    // layoutAlign/layoutGrow; the frame-only path above never reached them,
    // so modify(rect, {layoutAlign:"STRETCH"}) returned ok and changed nothing.
    if ("layoutAlign" in node && typeof props.layoutAlign === "string") {
      (node as LayoutMixin).layoutAlign = props.layoutAlign as LayoutMixin["layoutAlign"];
    }
    if ("layoutGrow" in node && typeof props.layoutGrow === "number") {
      (node as LayoutMixin).layoutGrow = props.layoutGrow;
    }
  }

  // Geometry.
  if (
    (typeof props.x === "number" || typeof props.y === "number") &&
    "x" in node
  ) {
    if (typeof props.x === "number") (node as LayoutMixin).x = props.x;
    if (typeof props.y === "number") (node as LayoutMixin).y = props.y;
  }
  // Accept both w/h and width/height (create takes both; modify used to accept
  // only w/h, so modify(id,{width,height}) silently dropped the resize).
  const reqW = typeof props.w === "number" ? props.w : (typeof props.width === "number" ? props.width : undefined);
  const reqH = typeof props.h === "number" ? props.h : (typeof props.height === "number" ? props.height : undefined);
  if ((reqW !== undefined || reqH !== undefined) && "resize" in node) {
    const l = node as LayoutMixin;
    const w = reqW !== undefined ? reqW : l.width;
    const h = reqH !== undefined ? reqH : l.height;
    (node as unknown as { resize(w: number, h: number): void }).resize(
      Math.max(0.01, w),
      Math.max(0.01, h),
    );
  }

  // Re-apply text sizing after any potential reparent quirk.
  if (node.type === "TEXT" && typeof props.textAutoResize === "string") {
    (node as TextNode).textAutoResize = props.textAutoResize as
      | "NONE"
      | "WIDTH_AND_HEIGHT"
      | "HEIGHT"
      | "TRUNCATE";
  }

  return { id: node.id, node: serializeNode(node, "compact") };
}

/** Text props Figma rejects unless the node's fonts are loaded. */
const TEXT_LAYOUT_KEYS = [
  "fontSize", "characters", "text", "textAlignHorizontal", "textAlignVertical",
  "textAutoResize", "lineHeight", "letterSpacing", "w", "h", "width", "height",
  // Stretching/growing a text layer in auto-layout re-lays its lines.
  "layoutAlign", "layoutGrow",
];

async function modifyText(
  node: TextNode,
  props: Record<string, unknown>,
  ctx: HandlerContext,
): Promise<void> {
  const fontName = (props.fontName ?? {}) as { family?: unknown; style?: unknown };
  const hasFamily = typeof props.fontFamily === "string" || typeof fontName.family === "string";
  const hasStyle = typeof props.fontStyle === "string" || typeof fontName.style === "string";
  if (hasFamily || hasStyle) {
    const family =
      typeof props.fontFamily === "string"
        ? props.fontFamily
        : typeof fontName.family === "string"
          ? fontName.family
          : DEFAULT_FONT.family;
    const style =
      typeof props.fontStyle === "string"
        ? props.fontStyle
        : typeof fontName.style === "string"
          ? fontName.style
          : DEFAULT_FONT.style;
    const res = await loadFontWithFallback({ family, style });
    node.fontName = res.resolvedFont;
    if (res.substituted && res.reason) ctx.warn(res.reason);
  } else if (TEXT_LAYOUT_KEYS.some((k) => props[k] !== undefined)) {
    // Only a change that re-lays the glyphs needs the node's fonts. Loading
    // them for every modify made modify(text, {x}) fail outright on a file
    // whose font isn't installed — the move never happened.
    await loadNodeFonts(node);
  }
  if (typeof props.fontSize === "number") node.fontSize = props.fontSize;
  // `create` has honoured these since text styles landed; `modify` did not, so
  // a line height set at creation could never be CHANGED — and the call
  // returned ok, so the only way to find out was to read the property back.
  // Reported from a real build: a badge stayed at 12.5/20 while its spec said
  // 12.5/16, which no screenshot can catch because the chip is a fixed height
  // and the text is centred in it.
  if (props.lineHeight !== undefined) node.lineHeight = parseLineHeight(props.lineHeight);
  if (props.letterSpacing !== undefined) node.letterSpacing = parseLetterSpacing(props.letterSpacing);
  if (typeof props.characters === "string") node.characters = props.characters;
  else if (typeof props.text === "string") node.characters = props.text;
  applyTextAlign(node, props);
}

function applyLayoutProps(node: FrameNode, props: Record<string, unknown>): void {
  const mode =
    typeof props.layoutMode === "string"
      ? props.layoutMode.toUpperCase()
      : undefined;
  if (mode === "HORIZONTAL" || mode === "VERTICAL" || mode === "NONE") {
    node.layoutMode = mode;
  }
  if (typeof props.itemSpacing === "number") node.itemSpacing = props.itemSpacing;
  const pad = normalizePadding(props);
  if (typeof pad.left === "number") node.paddingLeft = pad.left;
  if (typeof pad.right === "number") node.paddingRight = pad.right;
  if (typeof pad.top === "number") node.paddingTop = pad.top;
  if (typeof pad.bottom === "number") node.paddingBottom = pad.bottom;
  if (typeof props.primaryAxisSizingMode === "string") {
    node.primaryAxisSizingMode = props.primaryAxisSizingMode as "FIXED" | "AUTO";
  }
  // Wrapping, and the gap BETWEEN wrapped rows. `counterAxisSpacing` only
  // means anything once the frame wraps, which is why it is applied after.
  if (typeof props.layoutWrap === "string") {
    const wrap = props.layoutWrap.toUpperCase();
    if (wrap === "WRAP" || wrap === "NO_WRAP") node.layoutWrap = wrap;
  }
  if (typeof props.counterAxisSpacing === "number" && node.layoutWrap === "WRAP") {
    node.counterAxisSpacing = props.counterAxisSpacing;
  }
  if (typeof props.counterAxisSizingMode === "string") {
    node.counterAxisSizingMode = props.counterAxisSizingMode as "FIXED" | "AUTO";
  }
  if (typeof props.primaryAxisAlignItems === "string") {
    node.primaryAxisAlignItems = props.primaryAxisAlignItems as
      | "MIN"
      | "MAX"
      | "CENTER"
      | "SPACE_BETWEEN";
  }
  if (typeof props.counterAxisAlignItems === "string") {
    node.counterAxisAlignItems = props.counterAxisAlignItems as
      | "MIN"
      | "MAX"
      | "CENTER"
      | "BASELINE";
  }
  if (typeof props.layoutAlign === "string") {
    node.layoutAlign = props.layoutAlign as
      | "MIN"
      | "CENTER"
      | "MAX"
      | "STRETCH"
      | "INHERIT";
  }
  if (typeof props.layoutGrow === "number") node.layoutGrow = props.layoutGrow;
}

function applyCornerRadii(
  node: SceneNode,
  props: Record<string, unknown>,
): void {
  const uniform = resolveUniformCornerRadius(props);
  if (uniform !== undefined && "cornerRadius" in node) {
    (node as RectangleNode).cornerRadius = uniform;
  }
  for (const key of [
    "topLeftRadius",
    "topRightRadius",
    "bottomRightRadius",
    "bottomLeftRadius",
  ] as const) {
    if (typeof props[key] === "number" && key in node) {
      (node as unknown as Record<typeof key, number>)[key] = props[key] as number;
    }
  }
}

export async function deleteNode(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  const target = await findNode(p.nodeId ?? p.id);
  if (target?.type === "PAGE") {
    throw err(
      ErrorCode.INVALID_PARAMS,
      `"${target.name}" is a page — delete() removes layers.`,
      `Use deletePage("${target.id}") to remove a whole page.`,
    );
  }
  const node = await requireNode(p.nodeId ?? p.id);
  const force = p.force === true;
  const isComponent = node.type === "COMPONENT" || node.type === "COMPONENT_SET";
  let instances = 0;
  if (isComponent) {
    if ((node as ComponentNode).remote) {
      throw err(
        ErrorCode.UNSUPPORTED_OPERATION,
        `Component "${node.name}" comes from a library and is read-only here.`,
        "Delete it in the file that publishes the library.",
      );
    }
    const found = await (node as ComponentNode).getInstancesAsync?.();
    instances = found ? found.length : 0;
    if (instances > 0 && !force) {
      throw err(
        ErrorCode.COMPONENT_IN_USE,
        `Component "${node.name}" has ${instances} instance(s).`,
        "The instances stay on the canvas and can \"Restore component\" from the right sidebar. Re-run with force:true to proceed.",
      );
    }
  }
  const id = node.id;
  const parent = node.parent;
  // Removing the last variant makes Figma delete the set with it.
  const lastVariantOf =
    node.type === "COMPONENT" && parent?.type === "COMPONENT_SET" && parent.children.length === 1
      ? parent.name
      : undefined;
  node.remove();
  if (!isDetached(node)) {
    throw err(
      ErrorCode.INTERNAL,
      `Node "${id}" could not be removed (still present after remove()).`,
      "It may be locked or otherwise protected. Delete it in the Figma UI.",
    );
  }
  if (!isComponent) return { id, deleted: true };
  return {
    id,
    deleted: true,
    instancesLeft: instances,
    ...(instances > 0
      ? { note: `${instances} instance(s) stay on the canvas; each can "Restore component" from the right sidebar.` }
      : {}),
    ...(lastVariantOf ? { componentSetDeleted: lastVariantOf } : {}),
  };
}

/**
 * Is a node gone from the document? `removed` alone lies for a main
 * component: Figma soft-deletes it so its instances can restore it, so the
 * node object stays alive with `removed === false` — but it no longer has a
 * parent. Checking only `removed` reported every component delete as failed
 * while the component had in fact left the canvas.
 */
function isDetached(node: SceneNode): boolean {
  try {
    return node.removed || node.parent === null;
  } catch {
    return true; // a fully destroyed node throws on property access
  }
}

export async function move(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  const node = await requireNode(p.nodeId ?? p.id);
  if (typeof p.x === "number" && "x" in node) (node as LayoutMixin).x = p.x;
  if (typeof p.y === "number" && "y" in node) (node as LayoutMixin).y = p.y;
  if (p.parentId !== undefined) {
    const parent = await resolveParent(p.parentId);
    insertInto(parent, node, p.insertAt as InsertAt | undefined);
  } else if (p.insertAt !== undefined && node.parent && isParentNode(node.parent)) {
    insertInto(node.parent, node, p.insertAt as InsertAt);
  }
  return { id: node.id, node: serializeNode(node, "sparse") };
}

export async function resize(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  const node = await requireNode(p.nodeId ?? p.id);
  if (!("resize" in node)) {
    throw err(
      ErrorCode.INVALID_PARAMS,
      `Node type ${node.type} cannot be resized.`,
    );
  }
  const l = node as LayoutMixin;
  const w = typeof p.w === "number" ? p.w : typeof p.width === "number" ? p.width : l.width;
  const h = typeof p.h === "number" ? p.h : typeof p.height === "number" ? p.height : l.height;
  (node as unknown as { resize(w: number, h: number): void }).resize(
    Math.max(0.01, w),
    Math.max(0.01, h),
  );
  return { id: node.id, node: serializeNode(node, "sparse") };
}

export async function group(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  const ids = Array.isArray(p.nodeIds) ? p.nodeIds : [];
  if (ids.length === 0) {
    throw err(ErrorCode.INVALID_PARAMS, "group requires nodeIds[].");
  }
  const nodes: SceneNode[] = [];
  for (const id of ids) nodes.push(await requireNode(id));
  const parent = nodes[0]!.parent ?? figma.currentPage;
  const g = figma.group(nodes, parent as BaseNode & ChildrenMixin);
  if (typeof p.name === "string") g.name = p.name;
  return { id: g.id, node: serializeNode(g, "compact") };
}

export async function ungroup(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  const node = await requireNode(p.nodeId ?? p.id);
  if (node.type !== "GROUP" && node.type !== "FRAME") {
    throw err(
      ErrorCode.INVALID_PARAMS,
      `Only GROUP/FRAME can be ungrouped (got ${node.type}).`,
    );
  }
  const children = figma.ungroup(node as GroupNode);
  return { ids: children.map((c) => c.id) };
}

export async function flatten(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  const ids: string[] = Array.isArray(p.nodeIds)
    ? p.nodeIds
    : [String(p.nodeId ?? p.id)];
  const nodes: SceneNode[] = [];
  for (const id of ids) nodes.push(await requireNode(id));
  const parent = nodes[0]!.parent as (BaseNode & ChildrenMixin) | null;
  const vector = figma.flatten(nodes, parent ?? undefined);
  return { id: vector.id, node: serializeNode(vector, "sparse") };
}

export async function setSelection(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  const ids: string[] = Array.isArray(p.nodeIds)
    ? p.nodeIds
    : p.nodeId
      ? [String(p.nodeId)]
      : [];
  const nodes: SceneNode[] = [];
  for (const id of ids) {
    const n = await getNodeByIdSafe(id);
    if (n && n.type !== "PAGE" && n.type !== "DOCUMENT") {
      nodes.push(n as SceneNode);
    }
  }
  figma.currentPage.selection = nodes;
  return { selection: nodes.map((n) => n.id) };
}

export async function zoomToFit(ctx: HandlerContext): Promise<unknown> {
  const p = ctx.params;
  if (p.nodeId || p.nodeIds) {
    const ids: string[] = Array.isArray(p.nodeIds)
      ? p.nodeIds
      : [String(p.nodeId)];
    const nodes: SceneNode[] = [];
    for (const id of ids) nodes.push(await requireNode(id));
    figma.viewport.scrollAndZoomIntoView(nodes);
    return { zoomed: nodes.map((n) => n.id) };
  }
  figma.viewport.scrollAndZoomIntoView(figma.currentPage.children);
  return { zoomed: "page" };
}
